void backtrack(const string& s, string& path, vector<bool>& used) {
    if (path.size() == s.size()) {
        cout << path << endl;
        return;
    }
    for (int i = 0; i < s.size(); i++) {
        if (used[i]) continue;
        used[i] = true;
        path.push_back(s[i]);
        backtrack(s, path, used);
        path.pop_back();
        used[i] = false;
    }
}
