void solve(int row, int n, vector<int>& queens, vector<bool>& cols,
           vector<bool>& diag1, vector<bool>& diag2, vector<vector<string>>& res) {
    if (row == n) {
        vector<string> board(n, string(n, '.'));
        for (int i = 0; i < n; i++) board[i][queens[i]] = 'Q';
        res.push_back(board);
        return;
    }
    for (int col = 0; col < n; col++) {
        int d1 = row - col + n - 1, d2 = row + col;
        if (cols[col] || diag1[d1] || diag2[d2]) continue;
        queens[row] = col;
        cols[col] = diag1[d1] = diag2[d2] = true;
        solve(row + 1, n, queens, cols, diag1, diag2, res);
        cols[col] = diag1[d1] = diag2[d2] = false;
    }
}
int main() {
    int n = 4;
    vector<int> queens(n);
    vector<bool> cols(n), diag1(2 * n - 1), diag2(2 * n - 1);
    vector<vector<string>> res;
    solve(0, n, queens, cols, diag1, diag2, res);
    for (auto& b : res) {
        for (auto& r : b) cout << r << endl;
        cout << endl;
    }
    return 0;
}

