int intervalCover(vector<pair<int,int>>& intervals, int T) {
    sort(intervals.begin(), intervals.end());
    int count = 0, curEnd = 0, i = 0, n = intervals.size();
    while (curEnd < T) {
        int farthest = curEnd;
        while (i < n && intervals[i].first <= curEnd) {
            farthest = max(farthest, intervals[i].second);
            i++;
        }
        if (farthest == curEnd) return -1;
        count++;
        curEnd = farthest;
    }
    return count;
}
