#include <queue>
#include <climits>
using namespace std;
void dijkstra(int start, vector<vector<pair<int,int>>>& adj, vector<int>& dist) {
    dist[start] = 0;
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    pq.push({0, start});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto& [v, w] : adj[u])
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
    }
}
int main() {
    int n = 5;
    vector<vector<pair<int,int>>> adj(n);
    adj[0].push_back({1, 4});
    adj[0].push_back({2, 1});
    adj[2].push_back({1, 2});
    adj[2].push_back({3, 5});
    adj[1].push_back({3, 1});
    vector<int> dist(n, INT_MAX);
    dijkstra(0, adj, dist);
    for (int d : dist) cout << d << " ";
    return 0;
}

