#include <iostream>
#include <string>
#include <stack>
#include <unordered_map>
using namespace std;
bool isValid(string s) {
    stack<char> st;
    unordered_map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') st.push(c);
        else if (st.empty() || st.top() != pairs[c]) return false;
        else st.pop();
    }
    return st.empty();
}
int main() {
    string s = "{[()]}";
    cout << (isValid(s) ? "有效" : "无效");
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;
vector<int> mergeKArrays(vector<vector<int>>& arrays) {
    vector<int> result;
    using T = tuple<int, int, int>;
    priority_queue<T, vector<T>, greater<T>> pq;
    for (int i = 0; i < arrays.size(); i++)
        if (!arrays[i].empty()) pq.push({arrays[i][0], i, 0});
    while (!pq.empty()) {
        auto [val, arrIdx, elemIdx] = pq.top(); pq.pop();
        result.push_back(val);
        if (elemIdx + 1 < arrays[arrIdx].size())
            pq.push({arrays[arrIdx][elemIdx + 1], arrIdx, elemIdx + 1});
    }
    return result;
}
int main() {
    vector<vector<int>> arrays = {{1,4,7},{2,5,8},{3,6,9}};
    vector<int> res = mergeKArrays(arrays);
    for (int x : res) cout << x << " ";
    return 0;
}

#include <iostream>
